"use strict";
// O tipo primitivo "null" no TypeScript.
//
// Para que isso serve?
// Representa a ausência intencional e explícita de qualquer valor ou referência de objeto.
//
// Qual comportamento devo observar?
// A variável expressa propositalmente um estado sem valor por meio da atribuição do valor primitivo "null".
const identificadorCupom = null;
console.log(identificadorCupom);
